import { defineConfig } from 'vitest/config';

export default defineConfig({
  test: {
    name: 'core',
    include: ['src/**/*.test.ts', 'test/**/*.test.ts'],
    environment: 'node',
  },
});

/**
 * Money is represented as an integer amount in *minor units* (cents) plus a currency.
 * Floating point is never used for monetary arithmetic, which keeps totals exact
 * and makes the pricing engine deterministic across processes and replicas.
 */
export interface Money {
  readonly amount: number;
  readonly currency: string;
}

export class InvalidMoneyError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'InvalidMoneyError';
  }
}

const CURRENCY_PATTERN = /^[A-Z]{3}$/;

export function money(amount: number, currency: string): Money {
  if (!Number.isInteger(amount)) {
    throw new InvalidMoneyError(`Amount must be an integer in minor units, received: ${amount}`);
  }
  if (!Number.isSafeInteger(amount)) {
    throw new InvalidMoneyError(`Amount exceeds the safe integer range: ${amount}`);
  }
  const normalized = currency?.trim().toUpperCase() ?? '';
  if (!CURRENCY_PATTERN.test(normalized)) {
    throw new InvalidMoneyError(`Invalid ISO-4217 currency code: "${currency}"`);
  }
  return { amount, currency: normalized };
}

export function zero(currency: string): Money {
  return money(0, currency);
}

/** Converts a decimal value (e.g. 12.34) into minor units (1234). */
export function moneyFromDecimal(value: number, currency: string): Money {
  if (!Number.isFinite(value)) {
    throw new InvalidMoneyError(`Cannot convert non finite value to money: ${value}`);
  }
  return money(Math.round((value + Number.EPSILON) * 100), currency);
}

export function moneyToDecimal(value: Money): number {
  return value.amount / 100;
}

function assertSameCurrency(a: Money, b: Money): void {
  if (a.currency !== b.currency) {
    throw new InvalidMoneyError(`Currency mismatch: ${a.currency} vs ${b.currency}`);
  }
}

export function add(a: Money, b: Money): Money {
  assertSameCurrency(a, b);
  return money(a.amount + b.amount, a.currency);
}

export function subtract(a: Money, b: Money): Money {
  assertSameCurrency(a, b);
  return money(a.amount - b.amount, a.currency);
}

export function negate(a: Money): Money {
  return money(-a.amount, a.currency);
}

export function multiply(a: Money, factor: number): Money {
  if (!Number.isInteger(factor) || factor < 0) {
    throw new InvalidMoneyError(`Multiplier must be a non negative integer, received: ${factor}`);
  }
  return money(a.amount * factor, a.currency);
}

/** Applies a rate (0.21 == 21%) rounding half up to the nearest minor unit. */
export function applyRate(a: Money, rate: number): Money {
  if (!Number.isFinite(rate) || rate < 0) {
    throw new InvalidMoneyError(`Rate must be a positive finite number, received: ${rate}`);
  }
  return money(Math.round(a.amount * rate), a.currency);
}

export function sumMoney(items: readonly Money[], currency: string): Money {
  return items.reduce<Money>((acc, item) => add(acc, item), zero(currency));
}

export function compare(a: Money, b: Money): number {
  assertSameCurrency(a, b);
  if (a.amount === b.amount) return 0;
  return a.amount < b.amount ? -1 : 1;
}

export function isZero(a: Money): boolean {
  return a.amount === 0;
}

export function isNegative(a: Money): boolean {
  return a.amount < 0;
}

export function max(a: Money, b: Money): Money {
  assertSameCurrency(a, b);
  return a.amount >= b.amount ? a : b;
}

export function min(a: Money, b: Money): Money {
  assertSameCurrency(a, b);
  return a.amount <= b.amount ? a : b;
}

export function clampNonNegative(a: Money): Money {
  return a.amount < 0 ? zero(a.currency) : a;
}

export function formatMoney(a: Money, locale = 'es-ES'): string {
  return new Intl.NumberFormat(locale, { style: 'currency', currency: a.currency }).format(
    a.amount / 100,
  );
}

/**
 * Domain errors are the single source of truth for "why did this fail".
 * The HTTP layer maps them to status codes, so the domain never depends on
 * transport concerns.
 */
export type DomainErrorCode =
  | 'CART_NOT_FOUND'
  | 'CART_CONFLICT'
  | 'CART_IMMUTABLE'
  | 'CART_LIMIT_EXCEEDED'
  | 'INVALID_QUANTITY'
  | 'PRODUCT_NOT_FOUND'
  | 'PRODUCT_UNAVAILABLE'
  | 'COUPON_INVALID'
  | 'COUPON_EXPIRED'
  | 'COUPON_MIN_SUBTOTAL'
  | 'INSUFFICIENT_STOCK'
  | 'FORBIDDEN'
  | 'IDEMPOTENCY_CONFLICT'
  | 'CHECKOUT_FAILED';

export class DomainError extends Error {
  readonly code: DomainErrorCode;
  readonly details: Record<string, unknown>;

  constructor(code: DomainErrorCode, message: string, details: Record<string, unknown> = {}) {
    super(message);
    this.name = new.target.name;
    this.code = code;
    this.details = details;
    Error.captureStackTrace?.(this, new.target);
  }

  toJSON(): { code: DomainErrorCode; message: string; details: Record<string, unknown> } {
    return { code: this.code, message: this.message, details: this.details };
  }
}

export class CartNotFoundError extends DomainError {
  constructor(cartId: string) {
    super('CART_NOT_FOUND', `Cart "${cartId}" was not found`, { cartId });
  }
}

export class CartConflictError extends DomainError {
  constructor(cartId: string, expectedVersion: number, actualVersion: number) {
    super(
      'CART_CONFLICT',
      `Cart "${cartId}" was modified concurrently (expected version ${expectedVersion}, current ${actualVersion})`,
      { cartId, expectedVersion, actualVersion },
    );
  }
}

export class CartImmutableError extends DomainError {
  constructor(cartId: string) {
    super('CART_IMMUTABLE', `Cart "${cartId}" is not modifiable anymore`, { cartId });
  }
}

export class CartLimitExceededError extends DomainError {
  constructor(limit: string, max: number, actual: number) {
    super('CART_LIMIT_EXCEEDED', `Cart limit "${limit}" exceeded (max ${max}, got ${actual})`, {
      limit,
      max,
      actual,
    });
  }
}

export class InvalidQuantityError extends DomainError {
  constructor(quantity: number, min = 1, max = Number.MAX_SAFE_INTEGER) {
    super('INVALID_QUANTITY', `Quantity must be between ${min} and ${max}, received: ${quantity}`, {
      quantity,
      min,
      max,
    });
  }
}

export class ProductNotFoundError extends DomainError {
  constructor(productId: string) {
    super('PRODUCT_NOT_FOUND', `Product "${productId}" was not found`, { productId });
  }
}

export class ProductUnavailableError extends DomainError {
  constructor(productId: string, reason: string) {
    super('PRODUCT_UNAVAILABLE', `Product "${productId}" is not available: ${reason}`, { productId });
  }
}

export class CouponError extends DomainError {
  constructor(code: DomainErrorCode, message: string, details: Record<string, unknown> = {}) {
    super(code, message, details);
  }
}

export class InsufficientStockError extends DomainError {
  constructor(productId: string, requested: number, available: number) {
    super(
      'INSUFFICIENT_STOCK',
      `Not enough stock for product "${productId}" (requested ${requested}, available ${available})`,
      { productId, requested, available },
    );
  }
}

export class ForbiddenError extends DomainError {
  constructor(message: string, details: Record<string, unknown> = {}) {
    super('FORBIDDEN', message, details);
  }
}

export class IdempotencyConflictError extends DomainError {
  constructor(key: string) {
    super(
      'IDEMPOTENCY_CONFLICT',
      `Idempotency key "${key}" was already used with a different request payload`,
      { key },
    );
  }
}

export class CheckoutFailedError extends DomainError {
  constructor(message: string, details: Record<string, unknown> = {}) {
    super('CHECKOUT_FAILED', message, details);
  }
}

import type { Money } from './money.js';

/**
 * The catalog is a *separate* bounded context in the real world. The cart only
 * keeps a price snapshot on every line so the total the user sees never changes
 * under their feet; a background job can reconcile snapshots later.
 */
export interface CatalogProduct {
  readonly id: string;
  readonly sku: string;
  readonly name: string;
  readonly description?: string;
  readonly price: Money;
  readonly currency: string;
  readonly active: boolean;
  readonly stock?: number;
  readonly imageUrl?: string;
  readonly category?: string;
  readonly attributes?: Record<string, string>;
}

export interface CatalogQuery {
  readonly category?: string;
  readonly search?: string;
  readonly limit?: number;
  readonly offset?: number;
}

export function productRef(product: CatalogProduct): {
  id: string;
  sku: string;
  name: string;
  price: Money;
} {
  return { id: product.id, sku: product.sku, name: product.name, price: product.price };
}

import type { Money } from './money.js';
import type { DomainErrorCode } from './errors.js';

export type DiscountType = 'percentage' | 'fixed_amount' | 'free_shipping';

export interface AppliedCoupon {
  readonly code: string;
  readonly type: DiscountType;
  readonly value: number;
  readonly description: string;
  readonly appliedAt: string;
  readonly discountAmount: Money;
}

/**
 * A coupon that has been *validated* against the cart. Definition objects come
 * from the pricing rules provider, the resolved ones carry the actual money.
 */
export interface CouponDefinition {
  readonly code: string;
  readonly type: DiscountType;
  /** percentage: 0.1 == 10%. fixed_amount: amount in minor units. */
  readonly value: number;
  readonly description: string;
  readonly minSubtotal?: Money;
  readonly maxDiscount?: Money;
  readonly expiresAt?: string;
  readonly active: boolean;
}

export interface Promotion {
  readonly id: string;
  readonly type: DiscountType;
  readonly value: number;
  readonly description: string;
  readonly minSubtotal?: Money;
  readonly maxDiscount?: Money;
  readonly startsAt?: string;
  readonly endsAt?: string;
  readonly priority: number;
}

export interface ShippingPolicy {
  readonly flatAmount: Money;
  readonly freeAbove?: Money;
  readonly taxRate: number;
}

export interface CouponRejection {
  readonly code: DomainErrorCode;
  readonly reason: string;
}

