private async mutate<T>(cartId: string, ctx: RequestContext, mutator: (cart: Cart) => Cart): Promise<Cart> {
  let attempt = 0;
  let lastError: unknown;
  while (attempt < this.deps.policies.retryAttempts) {
    const current = await this.requireCart(cartId, ctx);
    const next = mutator(current);
    try {
      return await this.deps.carts.save(next, current.version);
    } catch (error) {
      if (error instanceof CartConflictError) { attempt++; await sleep(backoff); continue; }
      throw error;
    }
  }
  throw lastError ?? new CartConflictError(...);
}
```

