import type { Cache } from '../../application/ports.js';

interface Entry {
  value: unknown;
  expiresAt: number;
}

/** TTL cache with LRU-ish eviction, used when Redis is not configured. */
export class InMemoryCache implements Cache {
  private readonly entries = new Map<string, Entry>();

  constructor(private readonly maxEntries = 1000) {}

  async get<T>(key: string): Promise<T | null> {
    const entry = this.entries.get(key);
    if (!entry) return null;
    if (entry.expiresAt <= Date.now()) {
      this.entries.delete(key);
      return null;
    }
    return entry.value as T;
  }

  async set<T>(key: string, value: T, ttlMs: number): Promise<void> {
    if (this.entries.size >= this.maxEntries) {
      const oldest = this.entries.keys().next();
      if (!oldest.done) this.entries.delete(oldest.value);
    }
    this.entries.set(key, { value, expiresAt: Date.now() + ttlMs });
  }

  async delete(key: string): Promise<void> {
    this.entries.delete(key);
  }

  clear(): void {
    this.entries.clear();
  }
}

import type { DomainEvent } from '../../domain/events.js';
import type { EventPublisher, EventSubscriber } from '../../application/ports.js';

/**
 * In-process event bus. The Redis implementation publishes to a channel so any
 * replica can react to the events of any other replica.
 */
export class InMemoryEventBus implements EventPublisher, EventSubscriber {
  private readonly handlers = new Set<(event: DomainEvent) => void>();

  async publish(event: DomainEvent): Promise<void> {
    this.emit(event);
  }

  async publishAll(events: readonly DomainEvent[]): Promise<void> {
    for (const event of events) this.emit(event);
  }

  subscribe(handler: (event: DomainEvent) => void): () => void {
    this.handlers.add(handler);
    return () => this.handlers.delete(handler);
  }

  private emit(event: DomainEvent): void {
    for (const handler of [...this.handlers]) {
      try {
        handler(event);
      } catch {
        // A failing subscriber must not break the publisher.
      }
    }
  }
}

import type { IdempotencyRecord, IdempotencyStore } from '../../application/ports.js';

interface Stored extends IdempotencyRecord {
  expiresAt: number;
}

/**
 * In-memory idempotency store. The Redis adapter guarantees the same
 * semantics across replicas.
 */
export class InMemoryIdempotencyStore implements IdempotencyStore {
  private readonly records = new Map<string, Stored>();

  async get(key: string): Promise<IdempotencyRecord | null> {
    const record = this.records.get(key);
    if (!record) return null;
    if (record.expiresAt <= Date.now()) {
      this.records.delete(key);
      return null;
    }
    return record;
  }

  async put(record: IdempotencyRecord, ttlSeconds: number): Promise<void> {
    this.records.set(record.key, { ...record, expiresAt: Date.now() + ttlSeconds * 1000 });
  }

  async reserve(key: string, requestHash: string, ttlSeconds: number): Promise<boolean> {
    const existing = this.records.get(key);
    if (existing && existing.expiresAt > Date.now()) {
      return existing.requestHash === requestHash;
    }
    this.records.set(key, {
      key,
      requestHash,
      statusCode: 0,
      body: null,
      createdAt: new Date().toISOString(),
      expiresAt: Date.now() + ttlSeconds * 1000,
    });
    return true;
  }
}

