import type { CartPolicies } from '@cart/core';
import { defaultCartPolicies } from '@cart/core';

export type CatalogSource = 'seed' | 'http';

export interface RedisConfig {
  /** `null` disables Redis: the app runs with the in-memory adapters. */
  readonly url: string | null;
  readonly keyPrefix: string;
  readonly connectTimeoutMs: number;
}

export interface PricingConfig {
  readonly currency: string;
  readonly taxRate: number;
  readonly shippingFlatAmount: number;
  readonly freeShippingThreshold: number | null;
}

export interface CatalogConfig {
  readonly source: CatalogSource;
  readonly url: string | null;
  readonly cacheTtlMs: number;
}

export interface AppConfig {
  readonly env: string;
  readonly host: string;
  readonly port: number;
  readonly logLevel: string;
  readonly bodyLimitBytes: number;
  readonly redis: RedisConfig;
  readonly cart: CartPolicies;
  readonly pricing: PricingConfig;
  readonly catalog: CatalogConfig;
  readonly idempotencyTtlSeconds: number;
  readonly writeRetries: number;
  readonly rateLimit: { readonly max: number; readonly timeWindowMs: number };
  readonly corsOrigin: string;
  readonly shutdownTimeoutMs: number;
}

const readString = (env: NodeJS.ProcessEnv, key: string, fallback: string): string => {
  const value = env[key];
  return value === undefined || value.trim() === '' ? fallback : value.trim();
};

const readNumber = (env: NodeJS.ProcessEnv, key: string, fallback: number): number => {
  const raw = env[key];
  if (raw === undefined || raw.trim() === '') return fallback;
  const parsed = Number(raw);
  if (!Number.isFinite(parsed)) {
    throw new Error(`Environment variable ${key} must be a number, received "${raw}"`);
  }
  return parsed;
};

const readOptionalNumber = (env: NodeJS.ProcessEnv, key: string): number | null => {
  const raw = env[key];
  if (raw === undefined || raw.trim() === '') return null;
  const parsed = Number(raw);
  if (!Number.isFinite(parsed)) {
    throw new Error(`Environment variable ${key} must be a number, received "${raw}"`);
  }
  return parsed;
};

const readBoolean = (env: NodeJS.ProcessEnv, key: string, fallback: boolean): boolean => {
  const raw = env[key];
  if (raw === undefined || raw.trim() === '') return fallback;
  return ['1', 'true', 'yes', 'on'].includes(raw.trim().toLowerCase());
};

export function loadConfig(env: NodeJS.ProcessEnv = process.env): AppConfig {
  const envName = readString(env, 'NODE_ENV', 'development');
  const currency = readString(env, 'CURRENCY', 'EUR').toUpperCase();
  const redisUrl = readString(env, 'REDIS_URL', '');

  const policies: CartPolicies = {
    ...defaultCartPolicies,
    maxQuantityPerLine: readNumber(env, 'MAX_QUANTITY_PER_LINE', defaultCartPolicies.maxQuantityPerLine),
    maxDistinctLines: readNumber(env, 'MAX_DISTINCT_LINES', defaultCartPolicies.maxDistinctLines),
    maxUnitsPerCart: readNumber(env, 'MAX_UNITS_PER_CART', defaultCartPolicies.maxUnitsPerCart),
    ttlSeconds: readNumber(env, 'CART_TTL_SECONDS', defaultCartPolicies.ttlSeconds),
  };

  const catalogSource = readString(env, 'CATALOG_SOURCE', 'seed').toLowerCase() as CatalogSource;
  if (catalogSource !== 'seed' && catalogSource !== 'http') {
    throw new Error(`CATALOG_SOURCE must be "seed" or "http", received "${catalogSource}"`);
  }

  const freeShippingThreshold = readOptionalNumber(env, 'FREE_SHIPPING_THRESHOLD');

  return {
    env: envName,
    host: readString(env, 'HOST', '0.0.0.0'),
    port: readNumber(env, 'PORT', 3000),
    logLevel: readString(env, 'LOG_LEVEL', envName === 'test' ? 'silent' : 'info'),
    bodyLimitBytes: readNumber(env, 'BODY_LIMIT_BYTES', 256 * 1024),
    redis: {
      url: redisUrl === '' ? null : redisUrl,
      keyPrefix: readString(env, 'REDIS_KEY_PREFIX', 'cart:'),
      connectTimeoutMs: readNumber(env, 'REDIS_CONNECT_TIMEOUT_MS', 5000),
    },
    cart: policies,
    pricing: {
      currency,
      taxRate: readNumber(env, 'TAX_RATE', 0.21),
      shippingFlatAmount: readNumber(env, 'SHIPPING_FLAT_AMOUNT', 499),
      freeShippingThreshold,
    },
    catalog: {
      source: catalogSource,
      url: readString(env, 'CATALOG_URL', '') || null,
      cacheTtlMs: readNumber(env, 'CATALOG_CACHE_TTL_MS', 30_000),
    },
    idempotencyTtlSeconds: readNumber(env, 'IDEMPOTENCY_TTL_SECONDS', 86_400),
    writeRetries: readNumber(env, 'CART_WRITE_RETRIES', 5),
    rateLimit: {
      max: readNumber(env, 'RATE_LIMIT_MAX', 300),
      timeWindowMs: readNumber(env, 'RATE_LIMIT_WINDOW_MS', 60_000),
    },
    corsOrigin: readString(env, 'CORS_ORIGIN', '*'),
    shutdownTimeoutMs: readNumber(env, 'SHUTDOWN_TIMEOUT_MS', 10_000),
  };
}

export const isProduction = (config: AppConfig): boolean => config.env === 'production';
export const readBooleanEnv = readBoolean;

import pino, { type Logger as PinoLogger } from 'pino';
import type { Logger } from '@cart/core';
import type { AppConfig } from '../config.js';

export function createLogger(config: AppConfig): Logger {
  const pinoLogger: PinoLogger = pino({
    level: config.logLevel,
    base: { service: 'cart-api', env: config.env },
    redact: {
      paths: ['req.headers.authorization', 'headers["x-customer-id"]'],
      remove: true,
    },
    ...(config.env === 'development' ? { transport: undefined } : {}),
  });

  const wrap = (logger: PinoLogger): Logger => ({
    debug: (message, meta) => logger.debug(meta ?? {}, message),
    info: (message, meta) => logger.info(meta ?? {}, message),
    warn: (message, meta) => logger.warn(meta ?? {}, message),
    error: (message, meta) => logger.error(meta ?? {}, message),
    child: (bindings) => wrap(logger.child(bindings)),
  });

  return wrap(pinoLogger);
}

export type Labels = Record<string, string | number>;

interface HistogramSeries {
  readonly buckets: number[];
  readonly counts: number[];
  readonly sum: number;
  readonly count: number;
}

const DEFAULT_BUCKETS = [0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1, 2.5, 5, 10];

/**
 * Minimal Prometheus compatible metrics registry.
 *
 * Implemented in-house (instead of pulling a client library) to keep the
 * dependency surface of the service minimal; the exposition format is the
 * standard text format, so it can be scraped by Prometheus/Grafana as is.
 */
export class MetricsRegistry {
  private readonly counters = new Map<string, { labels: Labels; value: number }>();
  private readonly gauges = new Map<string, { labels: Labels; value: number }>();
  private readonly histograms = new Map<string, HistogramSeries>();

  private key(name: string, labels: Labels): string {
    const entries = Object.entries(labels).sort(([a], [b]) => a.localeCompare(b));
    return `${name}{${entries.map(([k, v]) => `${k}="${String(v)}"`).join(',')}}`;
  }

  increment(name: string, labels: Labels = {}, delta = 1): void {
    const key = this.key(name, labels);
    const current = this.counters.get(key);
    if (current) {
      current.value += delta;
      return;
    }
    this.counters.set(key, { labels, value: delta });
  }

  setGauge(name: string, labels: Labels = {}, value = 0): void {
    this.gauges.set(this.key(name, labels), { labels, value });
  }

  observe(name: string, labels: Labels = {}, seconds = 0, buckets = DEFAULT_BUCKETS): void {
    const key = this.key(name, labels);
    let series = this.histograms.get(key);
    if (!series) {
      series = { buckets, counts: new Array(buckets.length).fill(0), sum: 0, count: 0 };
      this.histograms.set(key, series);
    }
    for (let index = 0; index < series.buckets.length; index += 1) {
      const bound = series.buckets[index];
      if (bound !== undefined && seconds <= bound) {
        series.counts[index] = (series.counts[index] ?? 0) + 1;
      }
    }
    series.sum += seconds;
    series.count += 1;
  }

  render(): string {
    const lines: string[] = [];

    for (const [key, entry] of this.counters) {
      const name = key.split('{')[0] ?? key;
      const labels = this.renderLabels(entry.labels);
      lines.push(`${name}${labels} ${entry.value}`);
    }

    for (const [key, entry] of this.gauges) {
      const name = key.split('{')[0] ?? key;
      const labels = this.renderLabels(entry.labels);
      lines.push(`${name}${labels} ${entry.value}`);
    }

    for (const [key, series] of this.histograms) {
      const name = key.split('{')[0] ?? key;
      const baseLabels = this.parseLabels(key);
      for (let index = 0; index < series.buckets.length; index += 1) {
        const bound = series.buckets[index] ?? 0;
        const labels = this.renderLabels({ ...baseLabels, le: String(bound) });
        lines.push(`${name}_bucket${labels} ${series.counts[index] ?? 0}`);
      }
      const infLabels = this.renderLabels({ ...baseLabels, le: '+Inf' });
      lines.push(`${name}_bucket${infLabels} ${series.count}`);
      lines.push(`${name}_sum${this.renderLabels(baseLabels)} ${series.sum}`);
      lines.push(`${name}_count${this.renderLabels(baseLabels)} ${series.count}`);
    }

    return `${lines.join('\n')}\n`;
  }

  private renderLabels(labels: Labels): string {
    const entries = Object.entries(labels).filter(([, value]) => value !== undefined);
    if (entries.length === 0) return '';
    return `{${entries.map(([k, v]) => `${k}="${String(v)}"`).join(',')}}`;
  }

  private parseLabels(key: string): Labels {
    const start = key.indexOf('{');
    const end = key.lastIndexOf('}');
    if (start === -1 || end === -1) return {};
    const body = key.slice(start + 1, end);
    if (body.trim() === '') return {};
    const labels: Labels = {};
    for (const part of body.split(',')) {
      const [rawKey, rawValue] = part.split('=');
      if (!rawKey || !rawValue) continue;
      labels[rawKey] = rawValue.replace(/^"|"$/g, '');
    }
    return labels;
  }
}

export const metricsRegistry = new MetricsRegistry();

export const CART_METRICS = {
  operations: 'cart_operations_total',
  conflicts: 'cart_conflicts_total',
  operationDuration: 'cart_operation_duration_seconds',
  eventsPublished: 'cart_events_published_total',
} as const;

export const HTTP_METRICS = {
  requests: 'http_requests_total',
  duration: 'http_request_duration_seconds',
  inFlight: 'http_requests_in_flight',
} as const;

import { createClient, type RedisClientType } from 'redis';
import type { Logger } from '@cart/core';
import type { RedisConfig } from '../../config.js';

export interface RedisConnection {
  readonly client: RedisClientType;
  readonly publisher: RedisClientType;
  readonly subscriber: RedisClientType;
  isReady(): boolean;
  close(): Promise<void>;
}

/**
 * One Redis connection is used for regular commands and two extra ones are
 * dedicated to publishing/subscribing (a subscribed connection cannot run
 * regular commands in RESP2).
 */
export async function createRedisConnection(
  config: RedisConfig,
  logger: Logger,
): Promise<RedisConnection> {
  if (!config.url) {
    throw new Error('REDIS_URL is required to create a Redis connection');
  }

  const options = {
    url: config.url,
    socket: { connectTimeout: config.connectTimeoutMs, reconnectStrategy: (retries: number) => {
      if (retries > 10) return new Error('Redis reconnect limit reached');
      return Math.min(retries * 100, 2000);
    } },
  };

  const client = createClient(options);
  client.on('error', (error: Error) => logger.error('redis client error', { error: error.message }));
  client.on('reconnecting', () => logger.warn('redis reconnecting'));

  await client.connect();

  const publisher = client.duplicate();
  publisher.on('error', (error: Error) => logger.error('redis publisher error', { error: error.message }));
  await publisher.connect();

  const subscriber = client.duplicate();
  subscriber.on('error', (error: Error) =>
    logger.error('redis subscriber error', { error: error.message }),
  );
  await subscriber.connect();

  return {
    client,
    publisher,
    subscriber,
    isReady: () => client.isReady,
    close: async () => {
      await Promise.allSettled([client.quit(), publisher.quit(), subscriber.quit()]);
    },
  };
}

/** Removes the characters that would break the Redis Cluster hash tags. */
export const sanitizePrefix = (prefix: string): string => prefix.replace(/[{}]/g, '');

import type { CartRepository, Logger } from '@cart/core';
import {
  CartConflictError,
  CartNotFoundError,
  type Cart,
} from '@cart/core';
import type { RedisClientType } from 'redis';
import { CREATE_CART_SCRIPT, SAVE_CART_SCRIPT } from './scripts.js';

export interface RedisCartRepositoryOptions {
  readonly keyPrefix: string;
  readonly ttlSeconds: number;
  readonly logger: Logger;
}

/**
 * Redis backed cart repository.
 *
 * Key layout (the `{...}` is the Redis Cluster hash tag, so every operation on
 * a cart stays inside the shard that owns it):
 *
 *   cart:{<cartId>}          -> JSON document of the cart
 *   cart:index:{<customerId>} -> set of cart ids owned by the customer
 */
export class RedisCartRepository implements CartRepository {
  private readonly prefix: string;
  private readonly ttlSeconds: number;
  private readonly logger: Logger;

  constructor(
    private readonly redis: RedisClientType,
    options: RedisCartRepositoryOptions,
  ) {
    this.prefix = options.keyPrefix;
    this.ttlSeconds = options.ttlSeconds;
    this.logger = options.logger;
  }

  private cartKey(cartId: string): string {
    return `${this.prefix}{${cartId}}`;
  }

  private indexKey(customerId: string): string {
    return `${this.prefix}index:{${customerId}}`;
  }

  async findById(cartId: string): Promise<Cart | null> {
    const raw = await this.redis.get(this.cartKey(cartId));
    if (raw === null) return null;
    try {
      return JSON.parse(raw) as Cart;
    } catch (error) {
      this.logger.error('corrupted cart payload in redis', { cartId, error: String(error) });
      throw new CartNotFoundError(cartId);
    }
  }

  async create(cart: Cart): Promise<Cart> {
    const result = (await this.redis.eval(CREATE_CART_SCRIPT, {
      keys: [this.cartKey(cart.id)],
      arguments: [JSON.stringify(cart), String(this.ttlSeconds)],
    })) as string[];

    if (result[0] === 'exists') {
      throw new CartConflictError(cart.id, 0, 0);
    }
    if (cart.customerId) {
      await this.redis.sAdd(this.indexKey(cart.customerId), cart.id);
      await this.redis.expire(this.indexKey(cart.customerId), this.ttlSeconds);
    }
    return cart;
  }

  async save(cart: Cart, expectedVersion: number): Promise<Cart> {
    const nextVersion = expectedVersion + 1;
    const payload: Cart = { ...cart, version: nextVersion };

    const result = (await this.redis.eval(SAVE_CART_SCRIPT, {
      keys: [this.cartKey(cart.id)],
      arguments: [String(expectedVersion), JSON.stringify(payload), String(this.ttlSeconds)],
    })) as string[];

    const status = result[0];
    if (status === 'not_found') throw new CartNotFoundError(cart.id);
    if (status === 'corrupt') {
      this.logger.error('corrupted cart payload in redis', { cartId: cart.id });
      throw new CartNotFoundError(cart.id);
    }
    if (status === 'conflict') {
      throw new CartConflictError(cart.id, expectedVersion, Number(result[1] ?? -1));
    }
    return payload;
  }

  async findActiveByCustomer(customerId: string): Promise<Cart | null> {
    const ids = await this.redis.sMembers(this.indexKey(customerId));
    if (ids.length === 0) return null;

    const carts = await Promise.all(ids.map((id) => this.findById(id)));
    const active = carts
      .filter((cart): cart is Cart => cart !== null && cart.status === 'active')
      .sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
    return active[0] ?? null;
  }

  async listByCustomer(customerId: string, limit = 20): Promise<Cart[]> {
    const ids = await this.redis.sMembers(this.indexKey(customerId));
    if (ids.length === 0) return [];

    const carts = await Promise.all(ids.map((id) => this.findById(id)));
    return carts
      .filter((cart): cart is Cart => cart !== null)
      .sort((a, b) => b.updatedAt.localeCompare(a.updatedAt))
      .slice(0, limit);
  }

  async delete(cartId: string): Promise<void> {
    const cart = await this.findById(cartId);
    await this.redis.del(this.cartKey(cartId));
    if (cart?.customerId) {
      await this.redis.sRem(this.indexKey(cart.customerId), cartId);
    }
  }
}

