import type { FastifyInstance, FastifyRequest } from 'fastify';
import fp from 'fastify-plugin';
import type { RequestContext } from '@cart/core';

declare module 'fastify' {
  interface FastifyRequest {
    /** Authenticated customer (null for guest carts). */
    customerId: string | null;
  }
}

/**
 * Resolves the caller identity.
 *
 * The demo uses a plain header as the identity provider; in a real system this
 * is where the JWT/session of the API gateway is validated. Everything
 * downstream of the plugin only deals with the `customerId` string.
 */
async function customerContextPlugin(app: FastifyInstance): Promise<void> {
  app.decorateRequest('customerId', null);

  app.addHook('onRequest', async (request: FastifyRequest) => {
    const header = request.headers['x-customer-id'];
    const value = Array.isArray(header) ? header[0] : header;
    request.customerId = typeof value === 'string' && value.trim() !== '' ? value.trim() : null;
  });
}

export const registerCustomerContext = fp(customerContextPlugin);

export const contextFrom = (request: FastifyRequest): RequestContext => ({
  customerId: request.customerId,
  requestId: request.id,
});

import { createHash } from 'node:crypto';
import type { FastifyReply, FastifyRequest } from 'fastify';
import type { IdempotencyStore } from '@cart/core';

export interface IdempotencyOptions {
  readonly store: IdempotencyStore;
  readonly ttlSeconds: number;
  readonly request: FastifyRequest;
  readonly reply: FastifyReply;
  readonly handler: () => Promise<unknown>;
  readonly statusCode?: number;
}

const hashPayload = (request: FastifyRequest): string =>
  createHash('sha256')
    .update(`${request.method}::${request.url}::${JSON.stringify(request.body ?? null)}`)
    .digest('hex');

/**
 * Makes a write endpoint idempotent.
 *
 * The key is claimed atomically before the operation runs, so a client that
 * retries after a timeout (or a proxy that replays the request) never creates
 * two carts, two reservations or two orders.
 */
export async function withIdempotency(options: IdempotencyOptions): Promise<void> {
  const { store, ttlSeconds, request, reply, handler } = options;
  const header = request.headers['idempotency-key'];
  const key = Array.isArray(header) ? header[0] : header;

  if (!key || key.trim() === '') {
    reply.code(options.statusCode ?? 200).send(await handler());
    return;
  }

  const requestHash = hashPayload(request);
  const claim = await store.claim(key, requestHash, ttlSeconds);

  if (claim === 'conflict') {
    reply.code(409).send({
      error: {
        code: 'IDEMPOTENCY_CONFLICT',
        message: `The idempotency key "${key}" was already used with a different payload`,
        requestId: request.id,
      },
    });
    return;
  }

  if (claim === 'replay') {
    const record = await store.get(key);
    if (record && record.statusCode > 0) {
      reply.header('idempotent-replay', 'true').code(record.statusCode).send(record.body);
      return;
    }
    reply.code(409).send({
      error: {
        code: 'IDEMPOTENCY_IN_PROGRESS',
        message: 'A request with the same idempotency key is still being processed',
        requestId: request.id,
      },
    });
    return;
  }

  const payload = await handler();
  const statusCode = options.statusCode ?? 200;
  await store.put(
    {
      key,
      requestHash,
      statusCode,
      body: payload,
      createdAt: new Date().toISOString(),
    },
    ttlSeconds,
  );
  reply.code(statusCode).send(payload);
}

