import type { FastifyInstance } from 'fastify';
import type { Container } from '../../container.js';

const serializeProduct = (product: {
  id: string;
  sku: string;
  name: string;
  description?: string;
  price: { amount: number; currency: string };
  category?: string;
  imageUrl?: string;
  stock?: number;
  attributes?: Record<string, string>;
}) => ({
  id: product.id,
  sku: product.sku,
  name: product.name,
  description: product.description ?? null,
  price: { amount: product.price.amount, currency: product.price.currency },
  category: product.category ?? null,
  imageUrl: product.imageUrl ?? null,
  stock: product.stock ?? null,
  attributes: product.attributes ?? {},
});

export async function registerProductRoutes(
  app: FastifyInstance,
  container: Container,
): Promise<void> {
  app.get('/api/v1/products', async (request, reply) => {
    const query = request.query as {
      category?: string;
      search?: string;
      limit?: string;
      offset?: string;
    };

    const products = await container.catalog.list({
      ...(query.category ? { category: query.category } : {}),
      ...(query.search ? { search: query.search } : {}),
      limit: query.limit ? Math.min(Number(query.limit) || 50, 100) : 50,
      offset: query.offset ? Math.max(Number(query.offset) || 0, 0) : 0,
    });

    reply.send({ products: products.map(serializeProduct), total: products.length });
  });
}

import type { FastifyInstance } from 'fastify';
import type { Container } from '../../container.js';

export async function registerHealthRoutes(app: FastifyInstance, container: Container): Promise<void> {
  app.get('/health/live', async (_request, reply) => {
    reply.send({ status: 'ok', uptime: process.uptime() });
  });

  app.get('/health/ready', async (_request, reply) => {
    const checks = await container.readiness();
    const ready = Object.values(checks).every(Boolean);
    reply.code(ready ? 200 : 503).send({ status: ready ? 'ok' : 'degraded', checks });
  });

  app.get('/metrics', async (_request, reply) => {
    reply.header('content-type', 'text/plain; version=0.0.4; charset=utf-8');
    reply.send(container.metrics.render());
  });
}

import type { FastifyInstance } from 'fastify';
import type { Container } from '../../container.js';
import { contextFrom } from '../plugins/context.js';

/**
 * Server-Sent Events endpoint.
 *
 * The client subscribes to the cart stream to keep several tabs (or two
 * devices) in sync. Events are fanned out through the event bus, so a change
 * performed on another replica reaches the browser too.
 */
export async function registerEventRoutes(app: FastifyInstance, container: Container): Promise<void> {
  app.get('/api/v1/carts/:cartId/events', async (request, reply) => {
    const { cartId } = request.params as { cartId: string };
    const ctx = contextFrom(request);

    // Authorise before opening the stream.
    await container.cartService.getCart(cartId, ctx);

    reply.raw.writeHead(200, {
      'content-type': 'text/event-stream',
      'cache-control': 'no-cache, no-transform',
      connection: 'keep-alive',
      'x-accel-buffering': 'no',
    });
    reply.raw.write(`event: open\ndata: ${JSON.stringify({ cartId })}\n\n`);

    const unsubscribe = await container.events.subscribe((event) => {
      if (event.cartId !== cartId) return;
      reply.raw.write(`event: cart\ndata: ${JSON.stringify(event)}\n\n`);
    });

    const heartbeat = setInterval(() => {
      reply.raw.write(': keep-alive\n\n');
    }, 15_000);

    const cleanup = (): void => {
      clearInterval(heartbeat);
      void unsubscribe();
    };

    request.raw.on('close', cleanup);
    request.raw.on('error', cleanup);
    reply.raw.on('close', cleanup);

    // Keep the handler pending until the connection is closed.
    await new Promise<void>((resolve) => {
      reply.raw.on('close', () => resolve());
    });
  });
}

