    const prefix = sanitizePrefix(config.redis.keyPrefix);
    carts = new RedisCartRepository(redis.client, {keyPrefix: prefix, ttlSeconds: config.cart.ttlSeconds, logger});
    stock = new RedisStockManager(redis.client, {keyPrefix: prefix, reservationTtlSeconds: 900, ids, logger});
