    // seed stock levels from catalog
  } else {
    const repo = new InMemoryCartRepository();
    carts = repo;
    stock = new InMemoryStockManager(seedStock, ids);
    cache = new InMemoryCache();
    idempotency = new InMemoryIdempotencyStore();
    events = new InMemoryEventBus();
  }

  // catalog
  const baseCatalog = config.catalog.source === 'http' && config.catalog.url
    ? new HttpProductCatalog(config.catalog.url)
    : new InMemoryProductCatalog();
  const catalog = new CachedProductCatalog(baseCatalog, cache, config.catalog.cacheTtlMs);

  const rules = new InMemoryPricingRules();  // could be Redis-backed

  const shipping: ShippingPolicy = {
    flatAmount: money(config.pricing.shippingFlatAmount, config.pricing.currency),
    freeAbove: config.pricing.freeShippingThreshold !== null ? money(...) : undefined,
    taxRate: config.pricing.taxRate,
