import { describe, expect, it } from 'vitest';
import {
  InvalidMoneyError,
  add,
  applyRate,
  money,
  moneyFromDecimal,
  multiply,
  subtract,
  sumMoney,
} from '../src/domain/money.js';

describe('money', () => {
  it('stores the amount in minor units', () => {
    expect(money(1290, 'EUR')).toEqual({ amount: 1290, currency: 'EUR' });
  });

  it('normalises the currency code', () => {
    expect(money(100, 'eur').currency).toBe('EUR');
  });

  it('rejects non integer amounts', () => {
    expect(() => money(12.5, 'EUR')).toThrow(InvalidMoneyError);
  });

  it('rejects invalid currency codes', () => {
    expect(() => money(100, 'EURO')).toThrow(InvalidMoneyError);
    expect(() => money(100, '')).toThrow(InvalidMoneyError);
  });

  it('adds and subtracts amounts of the same currency', () => {
    expect(add(money(100, 'EUR'), money(250, 'EUR')).amount).toBe(350);
    expect(subtract(money(100, 'EUR'), money(250, 'EUR')).amount).toBe(-150);
  });

  it('refuses to mix currencies', () => {
    expect(() => add(money(100, 'EUR'), money(100, 'USD'))).toThrow(InvalidMoneyError);
  });

  it('multiplies by an integer quantity', () => {
    expect(multiply(money(1290, 'EUR'), 3).amount).toBe(3870);
    expect(() => multiply(money(1290, 'EUR'), 1.5)).toThrow(InvalidMoneyError);
  });

  it('rounds the rate half up', () => {
    expect(applyRate(money(3079, 'EUR'), 0.21).amount).toBe(647);
    expect(applyRate(money(100, 'EUR'), 0.5).amount).toBe(50);
    expect(applyRate(money(101, 'EUR'), 0.5).amount).toBe(51);
  });

  it('converts decimal values without losing cents', () => {
    expect(moneyFromDecimal(12.34, 'EUR').amount).toBe(1234);
    expect(moneyFromDecimal(0.1, 'EUR').amount).toBe(10);
  });

  it('sums an empty list to zero', () => {
    expect(sumMoney([], 'EUR').amount).toBe(0);
  });
});

import { describe, expect, it } from 'vitest';
import {
  addLine,
  applyCoupon,
  cartSubtotal,
  clearLines,
  createCart,
  findLine,
  mergeCarts,
  removeLine,
  setLineQuantity,
  type Cart,
} from '../src/domain/cart.js';
import { defaultCartPolicies, mergePolicies } from '../src/domain/policies.js';
import { money } from '../src/domain/money.js';
import { CartLimitExceededError, InvalidQuantityError } from '../src/domain/errors.js';

const NOW = '2024-01-01T00:00:00.000Z';

const baseCart = (): Cart =>
  createCart({ id: 'cart-1', customerId: 'customer-1', currency: 'EUR', now: NOW });

const product = {
  productId: 'p1',
  sku: 'SKU-1',
  name: 'Producto',
  unitPrice: money(1000, 'EUR'),
  quantity: 1,
  lineId: 'line-1',
};

describe('cart domain', () => {
  it('starts empty and active', () => {
    const cart = baseCart();
    expect(cart.lines).toHaveLength(0);
    expect(cart.status).toBe('active');
    expect(cart.version).toBe(0);
  });

  it('adds a line', () => {
    const cart = addLine(baseCart(), product, NOW, defaultCartPolicies);
    expect(cart.lines).toHaveLength(1);
    expect(cart.lines[0]?.quantity).toBe(1);
    expect(cartSubtotal(cart).amount).toBe(1000);
  });

  it('merges the quantity when the product is added twice', () => {
    let cart = addLine(baseCart(), product, NOW, defaultCartPolicies);
    cart = addLine(cart, { ...product, lineId: 'line-2', quantity: 2 }, NOW, defaultCartPolicies);

    expect(cart.lines).toHaveLength(1);
    expect(cart.lines[0]?.quantity).toBe(3);
    expect(cart.lines[0]?.id).toBe('line-1');
  });

  it('rejects invalid quantities', () => {
    expect(() => addLine(baseCart(), { ...product, quantity: 0 }, NOW, defaultCartPolicies)).toThrow(
      InvalidQuantityError,
    );
    expect(() => addLine(baseCart(), { ...product, quantity: 1.5 }, NOW, defaultCartPolicies)).toThrow(
      InvalidQuantityError,
    );
  });

  it('enforces the maximum quantity per line', () => {
    const policies = mergePolicies(defaultCartPolicies, { maxQuantityPerLine: 3 });
    expect(() => addLine(baseCart(), { ...product, quantity: 4 }, NOW, policies)).toThrow(
      CartLimitExceededError,
    );
  });

  it('enforces the maximum number of distinct lines', () => {
    const policies = mergePolicies(defaultCartPolicies, { maxDistinctLines: 1 });
    const cart = addLine(baseCart(), product, NOW, policies);
    expect(() =>
      addLine(cart, { ...product, productId: 'p2', lineId: 'line-2' }, NOW, policies),
    ).toThrow(CartLimitExceededError);
  });

  it('enforces the maximum number of units', () => {
    const policies = mergePolicies(defaultCartPolicies, { maxUnitsPerCart: 2 });
    const cart = addLine(baseCart(), product, NOW, policies);
    expect(() => addLine(cart, { ...product, quantity: 2 }, NOW, policies)).toThrow(
      CartLimitExceededError,
    );
  });

  it('sets an absolute quantity and removes the line when it is zero', () => {
    let cart = addLine(baseCart(), product, NOW, defaultCartPolicies);
    cart = setLineQuantity(cart, 'p1', 5, NOW, defaultCartPolicies);
    expect(findLine(cart, 'p1')?.quantity).toBe(5);

    cart = setLineQuantity(cart, 'p1', 0, NOW, defaultCartPolicies);
    expect(findLine(cart, 'p1')).toBeUndefined();
  });

  it('removes and clears lines', () => {
    let cart = addLine(baseCart(), product, NOW, defaultCartPolicies);
    cart = addLine(cart, { ...product, productId: 'p2', lineId: 'line-2' }, NOW, defaultCartPolicies);

    cart = removeLine(cart, 'p1', NOW, defaultCartPolicies);
    expect(cart.lines).toHaveLength(1);

    cart = clearLines(cart, NOW);
    expect(cart.lines).toHaveLength(0);
  });

  it('stores the coupons without duplicating them', () => {
    const coupon = {
      code: 'welcome',
      type: 'percentage' as const,
      value: 0.1,
      description: '10%',
      active: true,
    };

    let cart = applyCoupon(baseCart(), coupon, NOW);
    cart = applyCoupon(cart, coupon, NOW);

    expect(cart.coupons).toHaveLength(1);
    expect(cart.coupons[0]?.code).toBe('WELCOME');
  });

  it('merges a guest cart into the customer cart', () => {
    const target = addLine(baseCart(), product, NOW, defaultCartPolicies);
    const source = addLine(
      createCart({ id: 'guest', customerId: null, currency: 'EUR', now: NOW }),
      { ...product, quantity: 2 },
      NOW,
      defaultCartPolicies,
    );

    const { merged, source: converted } = mergeCarts(target, source, NOW, defaultCartPolicies);

    expect(merged.lines).toHaveLength(1);
    expect(merged.lines[0]?.quantity).toBe(3);
    expect(converted.status).toBe('converted');
  });

  it('clamps the merged quantity to the maximum per line', () => {
    const policies = mergePolicies(defaultCartPolicies, { maxQuantityPerLine: 2 });
    const target = addLine(baseCart(), { ...product, quantity: 2 }, NOW, policies);
    const source = addLine(
      createCart({ id: 'guest', customerId: null, currency: 'EUR', now: NOW }),
      { ...product, quantity: 2 },
      NOW,
      policies,
    );

    const { merged } = mergeCarts(target, source, NOW, policies);
    expect(merged.lines[0]?.quantity).toBe(2);
  });

  it('keeps the customer cart id when merging', () => {
    const target = baseCart();
    const source = createCart({ id: 'guest', customerId: null, currency: 'EUR', now: NOW });
    const { merged } = mergeCarts(target, source, NOW, defaultCartPolicies);
    expect(merged.id).toBe('cart-1');
  });
});

import { describe, expect, it } from 'vitest';
import { priceCart, allocate } from '../src/application/pricing-engine.js';
import { addLine, applyCoupon, createCart, type Cart } from '../src/domain/cart.js';
import { money } from '../src/domain/money.js';
import type { CouponDefinition, Promotion, ShippingPolicy } from '../src/domain/coupon.js';

const NOW = '2024-01-01T00:00:00.000Z';
const NOW_DATE = new Date(NOW);

const shipping: ShippingPolicy = {
  flatAmount: money(499, 'EUR'),
  freeAbove: money(5000, 'EUR'),
  taxRate: 0.21,
};

const buildCart = (lines: { price: number; quantity: number }[]): Cart => {
  let cart = createCart({ id: 'cart', customerId: 'c1', currency: 'EUR', now: NOW });
  lines.forEach((line, index) => {
    cart = addLine(
      cart,
      {
        productId: `p${index}`,
        sku: `SKU-${index}`,
        name: `Producto ${index}`,
        unitPrice: money(line.price, 'EUR'),
        quantity: line.quantity,
        lineId: `line-${index}`,
      },
      NOW,
      { maxQuantityPerLine: 100, maxDistinctLines: 100, maxUnitsPerCart: 1000, mergeStrategy: 'sum', ttlSeconds: 60 },
    );
  });
  return cart;
};

describe('pricing engine', () => {
  it('computes an empty cart without shipping', () => {
    const totals = priceCart({ cart: buildCart([]), promotions: [], coupons: [], shipping }, NOW_DATE);
    expect(totals.subtotal.amount).toBe(0);
    expect(totals.shipping.amount).toBe(0);
    expect(totals.total.amount).toBe(0);
  });

  it('adds the shipping and the tax', () => {
    const totals = priceCart(
      { cart: buildCart([{ price: 1290, quantity: 2 }]), promotions: [], coupons: [], shipping },
      NOW_DATE,
    );

    expect(totals.subtotal.amount).toBe(2580);
    expect(totals.shipping.amount).toBe(499);
    expect(totals.taxableBase.amount).toBe(3079);
    expect(totals.tax.amount).toBe(647);
    expect(totals.total.amount).toBe(3726);
  });

  it('grants free shipping above the threshold', () => {
    const totals = priceCart(
      { cart: buildCart([{ price: 6000, quantity: 1 }]), promotions: [], coupons: [], shipping },
      NOW_DATE,
    );
    expect(totals.shipping.amount).toBe(0);
    expect(totals.freeShipping).toBe(true);
  });

  it('applies a percentage promotion with a maximum discount', () => {
    const promotion: Promotion = {
      id: 'p',
      type: 'percentage',
      value: 0.1,
      description: '10%',
      maxDiscount: money(500, 'EUR'),
      minSubtotal: money(1000, 'EUR'),
      priority: 1,
    };

    const totals = priceCart(
      { cart: buildCart([{ price: 10000, quantity: 1 }]), promotions: [promotion], coupons: [], shipping },
      NOW_DATE,
    );

    expect(totals.promotionDiscount.amount).toBe(500);
    expect(totals.total).toBeDefined();
  });

  it('ignores a promotion when the minimum subtotal is not reached', () => {
    const promotion: Promotion = {
      id: 'p',
      type: 'percentage',
      value: 0.1,
      description: '10%',
      minSubtotal: money(5000, 'EUR'),
      priority: 1,
    };

    const totals = priceCart(
      { cart: buildCart([{ price: 1000, quantity: 1 }]), promotions: [promotion], coupons: [], shipping },
      NOW_DATE,
    );
    expect(totals.promotionDiscount.amount).toBe(0);
  });

  it('does not grant free shipping when the minimum subtotal is not reached', () => {
    const promotion: Promotion = {
      id: 'p',
      type: 'free_shipping',
      value: 0,
      description: 'envío gratis',
      minSubtotal: money(5000, 'EUR'),
      priority: 1,
    };

    const totals = priceCart(
      { cart: buildCart([{ price: 1000, quantity: 1 }]), promotions: [promotion], coupons: [], shipping },
      NOW_DATE,
    );
    expect(totals.shipping.amount).toBe(499);
    expect(totals.freeShipping).toBe(false);
  });

  it('applies a coupon on top of the subtotal', () => {
    const coupon: CouponDefinition = {
      code: 'WELCOME',
      type: 'percentage',
      value: 0.1,
      description: '10%',
      active: true,
    };

    const cart = applyCoupon(buildCart([{ price: 3450, quantity: 1 }]), coupon, NOW);
    const totals = priceCart({ cart, promotions: [], coupons: [coupon], shipping }, NOW_DATE);

    expect(totals.couponDiscount.amount).toBe(345);
    expect(totals.appliedCoupons[0]?.discountAmount.amount).toBe(345);
    expect(totals.items[0]?.discount.amount).toBe(345);
  });

  it('applies a fixed amount coupon', () => {
    const coupon: CouponDefinition = {
      code: 'VERANO25',
      type: 'fixed_amount',
      value: 2500,
      description: '25 €',
      active: true,
    };

    const cart = applyCoupon(buildCart([{ price: 10000, quantity: 1 }]), coupon, NOW);
    const totals = priceCart({ cart, promotions: [], coupons: [coupon], shipping }, NOW_DATE);

    expect(totals.couponDiscount.amount).toBe(2500);
    expect(totals.shipping.amount).toBe(0);
  });

  it('never discounts more than the subtotal', () => {
    const coupon: CouponDefinition = {
      code: 'HUGE',
      type: 'fixed_amount',
      value: 100000,
      description: '1000 €',
      active: true,
    };

    const cart = applyCoupon(buildCart([{ price: 1000, quantity: 1 }]), coupon, NOW);
    const totals = priceCart({ cart, promotions: [], coupons: [coupon], shipping }, NOW_DATE);

    expect(totals.couponDiscount.amount).toBe(1000);
    expect(totals.total.amount).toBe(0);
  });

  it('splits the discount across the lines keeping the sum exact', () => {
    const coupon: CouponDefinition = {
      code: 'ODD',
      type: 'fixed_amount',
      value: 1000,
      description: '10 €',
      active: true,
    };

    const cart = applyCoupon(
      buildCart([
        { price: 333, quantity: 1 },
        { price: 333, quantity: 1 },
        { price: 334, quantity: 1 },
      ]),
      coupon,
      NOW,
    );
    const totals = priceCart({ cart, promotions: [], coupons: [coupon], shipping }, NOW_DATE);

    const allocated = totals.items.reduce((acc, item) => acc + item.discount.amount, 0);
    expect(allocated).toBe(1000);
    expect(totals.discountTotal.amount).toBe(1000);
  });

  it('allocates with the largest remainder method', () => {
    expect(allocate(100, [1, 1, 1])).toEqual([34, 33, 33]);
    expect(allocate(10, [5, 5])).toEqual([5, 5]);
    expect(allocate(0, [5, 5])).toEqual([0, 0]);
  });
});

import { describe, expect, it } from 'vitest';
import {
  CartConflictError,
  CartService,
  InMemoryCartRepository,
  InMemoryEventBus,
  InMemoryIdempotencyStore,
  InMemoryPricingRules,
  InMemoryProductCatalog,
  InMemoryStockManager,
  defaultCartPolicies,
  money,
  systemClock,
  uuidGenerator,
  type CartRepository,
  type ProductCatalog,
} from '../src/index.js';

const buildService = (overrides: {
  carts?: CartRepository;
  catalog?: ProductCatalog;
} = {}) => {
  const carts = overrides.carts ?? new InMemoryCartRepository();
  const catalog = overrides.catalog ?? new InMemoryProductCatalog();
  const events = new InMemoryEventBus();
  const stock = new InMemoryStockManager({ 'sku-espresso': 10, 'sku-bolas': 100 }, uuidGenerator);

  const service = new CartService(
    { carts, catalog, rules: new InMemoryPricingRules(), stock, events, clock: systemClock, ids: uuidGenerator },
    {
      policies: defaultCartPolicies,
      shipping: {
        flatAmount: money(499, 'EUR'),
        freeAbove: money(5000, 'EUR'),
        taxRate: 0.21,
      },
      currency: 'EUR',
      writeRetries: 5,
    },
  );

  return { service, carts, catalog, events, stock };
};

const customer = { customerId: 'customer-1' };

describe('cart service', () => {
  it('creates a cart and adds items', async () => {
    const { service } = buildService();
    const created = await service.createCart(customer.customerId);

    const view = await service.addItem(
      created.cart.id,
      { productId: 'sku-espresso', quantity: 2 },
      customer,
    );

    expect(view.cart.lines).toHaveLength(1);
    expect(view.totals.subtotal.amount).toBe(2580);
  });

  it('rejects an unknown product', async () => {
    const { service } = buildService();
    const created = await service.createCart(customer.customerId);

    await expect(
      service.addItem(created.cart.id, { productId: 'nope', quantity: 1 }, customer),
    ).rejects.toThrow(/not found/i);
  });

  it('does not allow a customer to read the cart of another customer', async () => {
    const { service } = buildService();
    const created = await service.createCart('customer-1');

    await expect(service.getCart(created.cart.id, { customerId: 'customer-2' })).rejects.toThrow(
      /another customer/i,
    );
  });

  it('claims a guest cart when the customer logs in', async () => {
    const { service } = buildService();
    const guest = await service.createCart(null);
    await service.addItem(guest.cart.id, { productId: 'sku-espresso', quantity: 1 }, {
      customerId: null,
    });

    const claimed = await service.getCart(guest.cart.id, customer);
    expect(claimed.cart.customerId).toBe('customer-1');
  });

  it('resolves the write conflicts by replaying the mutation', async () => {
    const { service, carts } = buildService();
    const created = await service.createCart(customer.customerId);

    // Simulates a concurrent writer: the stored version moves forward while
    // the service is mutating its own snapshot.
    const originalSave = carts.save.bind(carts);
    let interfered = false;
    carts.save = async (cart, expectedVersion) => {
      if (!interfered) {
        interfered = true;
        await originalSave({ ...cart }, expectedVersion);
      }
      return originalSave(cart, expectedVersion);
    };

    const view = await service.addItem(
      created.cart.id,
      { productId: 'sku-espresso', quantity: 1 },
      customer,
    );

    expect(view.cart.lines).toHaveLength(1);
    expect(view.cart.version).toBeGreaterThan(1);
  });

  it('fails when the conflict cannot be resolved', async () => {
    const { service, carts } = buildService();
    const created = await service.createCart(customer.customerId);

    carts.save = async () => {
      throw new CartConflictError(created.cart.id, 0, 99);
    };

    await expect(
      service.addItem(created.cart.id, { productId: 'sku-espresso', quantity: 1 }, customer),
    ).rejects.toThrow(CartConflictError);
  });

  it('merges the guest cart into the customer cart', async () => {
    const { service } = buildService();
    const guest = await service.createCart(null);
    await service.addItem(guest.cart.id, { productId: 'sku-espresso', quantity: 2 }, {
      customerId: null,
    });

    const target = await service.createCart(customer.customerId);
    await service.addItem(target.cart.id, { productId: 'sku-espresso', quantity: 1 }, customer);

    const merged = await service.mergeCarts(guest.cart.id, target.cart.id, customer);
    expect(merged.cart.lines[0]?.quantity).toBe(3);

    const guestAfter = await service.getCart(guest.cart.id, { customerId: null });
    expect(guestAfter.cart.status).toBe('converted');
  });

  it('publishes the domain events', async () => {
    const { service, events } = buildService();
    const received: string[] = [];
    await events.subscribe((event) => received.push(event.type));

    const created = await service.createCart(customer.customerId);
    await service.addItem(created.cart.id, { productId: 'sku-espresso', quantity: 1 }, customer);
    await service.removeItem(created.cart.id, 'sku-espresso', customer);

    expect(received).toEqual(['cart.created', 'cart.item_added', 'cart.item_removed']);
  });

  it('checks out and reserves the stock', async () => {
    const { service, stock } = buildService();
    const created = await service.createCart(customer.customerId);
    await service.addItem(created.cart.id, { productId: 'sku-espresso', quantity: 2 }, customer);

    const result = await service.checkout(created.cart.id, customer);

    expect(result.cart.status).toBe('converted');
    expect(result.reservationId).toBeTruthy();
    expect(await stock.available('sku-espresso')).toBe(8);
  });

  it('refuses to check out an empty cart', async () => {
    const { service } = buildService();
    const created = await service.createCart(customer.customerId);

    await expect(service.checkout(created.cart.id, customer)).rejects.toThrow(/empty/i);
  });

  it('applies and removes coupons', async () => {
    const { service } = buildService();
    const created = await service.createCart(customer.customerId);
    await service.addItem(created.cart.id, { productId: 'sku-tostado', quantity: 1 }, customer);

    const withCoupon = await service.applyCoupon(created.cart.id, 'BIENVENIDA10', customer);
    expect(withCoupon.totals.couponDiscount.amount).toBe(345);

    const withoutCoupon = await service.removeCoupon(created.cart.id, 'BIENVENIDA10', customer);
    expect(withoutCoupon.totals.couponDiscount.amount).toBe(0);
  });

  it('keeps the idempotency store usable', async () => {
    const store = new InMemoryIdempotencyStore();
    expect(await store.claim('k', 'hash', 60)).toBe('claimed');
    expect(await store.claim('k', 'hash', 60)).toBe('replay');
    expect(await store.claim('k', 'other', 60)).toBe('conflict');
  });
});

