import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

const apiTarget = process.env.VITE_API_PROXY_TARGET ?? 'http://localhost:3000';

export default defineConfig({
  plugins: [react()],
  server: {
    port: 5173,
    host: true,
    proxy: {
      '/api': { target: apiTarget, changeOrigin: true },
    },
  },
  build: {
    outDir: 'dist',
    sourcemap: true,
  },
});

export interface Money {
  amount: number;
  currency: string;
}

export interface CatalogProduct {
  id: string;
  sku: string;
  name: string;
  description: string | null;
  price: Money;
  category: string | null;
  imageUrl: string | null;
  stock: number | null;
  attributes: Record<string, string>;
}

export interface CartLine {
  id: string;
  productId: string;
  sku: string;
  name: string;
  quantity: number;
  unitPrice: Money;
  lineTotal: Money;
  addedAt: string;
  updatedAt: string;
  metadata?: Record<string, string>;
}

export interface AppliedCoupon {
  code: string;
  type: string;
  value: number;
  description: string;
  appliedAt: string;
  discountAmount: Money;
}

export interface CartTotals {
  currency: string;
  subtotal: Money;
  promotionDiscount: Money;
  couponDiscount: Money;
  discountTotal: Money;
  shipping: Money;
  freeShipping: boolean;
  taxableBase: Money;
  tax: Money;
  total: Money;
  unitCount: number;
  distinctItems: number;
  items: {
    lineId: string;
    productId: string;
    sku: string;
    name: string;
    quantity: number;
    unitPrice: Money;
    subtotal: Money;
    discount: Money;
    total: Money;
  }[];
  appliedCoupons: AppliedCoupon[];
  appliedPromotions: { id: string; type: string; description: string }[];
}

export interface Cart {
  id: string;
  customerId: string | null;
  status: 'active' | 'converted' | 'abandoned';
  currency: string;
  version: number;
  createdAt: string;
  updatedAt: string;
  lines: CartLine[];
  coupons: AppliedCoupon[];
}

export interface CartView {
  cart: Cart;
  totals: CartTotals;
}

export interface CheckoutResult extends CartView {
  reservationId: string;
}

export interface ApiError {
  code: string;
  message: string;
  details?: Record<string, unknown>;
  requestId: string;
}

import type {
  CartView,
  CatalogProduct,
  CheckoutResult,
  ApiError,
} from '../types';

const BASE_URL = (import.meta.env.VITE_API_BASE_URL as string | undefined) ?? '/api/v1';

export class CartApiError extends Error {
  readonly status: number;
  readonly code: string;
  readonly details: Record<string, unknown>;

  constructor(status: number, payload: ApiError) {
    super(payload.message);
    this.name = 'CartApiError';
    this.status = status;
    this.code = payload.code;
    this.details = payload.details ?? {};
  }
}

export interface RequestOptions {
  readonly customerId: string | null;
  readonly idempotencyKey?: string;
  readonly signal?: AbortSignal;
}

const headersFor = (options: RequestOptions, withBody = false): HeadersInit => {
  const headers: Record<string, string> = { accept: 'application/json' };
  if (options.customerId) headers['x-customer-id'] = options.customerId;
  if (options.idempotencyKey) headers['idempotency-key'] = options.idempotencyKey;
  if (withBody) headers['content-type'] = 'application/json';
  return headers;
};

const request = async <T>(
  path: string,
  init: RequestInit,
  options: RequestOptions,
): Promise<T> => {
  const response = await fetch(`${BASE_URL}${path}`, {
    ...init,
    headers: { ...(init.headers as Record<string, string> | undefined), ...headersFor(options) },
    ...(options.signal ? { signal: options.signal } : {}),
  });

  if (!response.ok) {
    let payload: ApiError = {
      code: 'UNKNOWN_ERROR',
      message: `Request failed with status ${response.status}`,
      requestId: '',
    };
    try {
      const body = (await response.json()) as { error?: ApiError };
      if (body.error) payload = body.error;
    } catch {
      /* the body was not a JSON problem document */
    }
    throw new CartApiError(response.status, payload);
  }

  if (response.status === 204) return undefined as T;
  return (await response.json()) as T;
};

export const cartApi = {
  listProducts: (options: RequestOptions): Promise<{ products: CatalogProduct[]; total: number }> =>
    request('/products', { method: 'GET' }, options),

  createCart: (options: RequestOptions): Promise<CartView> =>
    request('/carts', { method: 'POST' }, options),

  getCart: (cartId: string, options: RequestOptions): Promise<CartView> =>
    request(`/carts/${encodeURIComponent(cartId)}`, { method: 'GET' }, options),

  addItem: (
    cartId: string,
    productId: string,
    quantity: number,
    options: RequestOptions,
  ): Promise<CartView> =>
    request(`/carts/${encodeURIComponent(cartId)}/items`, {
      method: 'POST',
      body: JSON.stringify({ productId, quantity }),
    }, options),

  updateQuantity: (
    cartId: string,
    productId: string,
    quantity: number,
    options: RequestOptions,
  ): Promise<CartView> =>
    request(
      `/carts/${encodeURIComponent(cartId)}/items/${encodeURIComponent(productId)}`,
      { method: 'PATCH', body: JSON.stringify({ quantity }) },
      options,
    ),

  removeItem: (cartId: string, productId: string, options: RequestOptions): Promise<CartView> =>
    request(`/carts/${encodeURIComponent(cartId)}/items/${encodeURIComponent(productId)}`, {
      method: 'DELETE',
    }, options),

  clear: (cartId: string, options: RequestOptions): Promise<CartView> =>
    request(`/carts/${encodeURIComponent(cartId)}/items`, { method: 'DELETE' }, options),

  applyCoupon: (cartId: string, code: string, options: RequestOptions): Promise<CartView> =>
    request(`/carts/${encodeURIComponent(cartId)}/coupons`, {
      method: 'POST',
      body: JSON.stringify({ code }),
    }, options),

  removeCoupon: (cartId: string, code: string, options: RequestOptions): Promise<CartView> =>
    request(`/carts/${encodeURIComponent(cartId)}/coupons/${encodeURIComponent(code)}`, {
      method: 'DELETE',
    }, options),

  checkout: (cartId: string, options: RequestOptions): Promise<CheckoutResult> =>
    request(`/carts/${encodeURIComponent(cartId)}/checkout`, { method: 'POST' }, options),

  merge: (cartId: string, sourceCartId: string, options: RequestOptions): Promise<CartView> =>
    request(`/carts/${encodeURIComponent(cartId)}/merge`, {
      method: 'POST',
      body: JSON.stringify({ sourceCartId }),
    }, options),
};

export const eventsUrl = (cartId: string): string =>
  `${BASE_URL}/carts/${encodeURIComponent(cartId)}/events`;

