export const formatMoney = (money: { amount: number; currency: string }): string =>
  new Intl.NumberFormat('es-ES', { style: 'currency', currency: money.currency }).format(
    money.amount / 100,
  );

import type { CatalogProduct } from '../types';
import { formatMoney } from '../lib/format';

interface ProductCardProps {
  product: CatalogProduct;
  onAdd: (productId: string) => void;
  pending: boolean;
  inCart: number;
}

export const ProductCard = ({ product, onAdd, pending, inCart }: ProductCardProps) => (
  <article className="product-card">
    <div className="product-card__media">
      {product.imageUrl ? (
        <img src={product.imageUrl} alt={product.name} loading="lazy" />
      ) : (
        <span className="product-card__placeholder">{product.sku.slice(0, 2)}</span>
      )}
    </div>

    <div className="product-card__body">
      <span className="product-card__category">{product.category ?? 'general'}</span>
      <h3>{product.name}</h3>
      <p>{product.description}</p>

      <dl className="product-card__attributes">
        {Object.entries(product.attributes).slice(0, 3).map(([key, value]) => (
          <div key={key}>
            <dt>{key}</dt>
            <dd>{value}</dd>
          </div>
        ))}
      </dl>
    </div>

    <footer className="product-card__footer">
      <strong>{formatMoney(product.price)}</strong>
      <button
        type="button"
        onClick={() => onAdd(product.id)}
        disabled={pending}
        aria-label={`Añadir ${product.name} al carrito`}
      >
        {pending ? 'Añadiendo…' : 'Añadir'}
      </button>
      {inCart > 0 && <span className="badge">{inCart} en el carrito</span>}
    </footer>
  </article>
);

import { useState } from 'react';
import type { CartTotals } from '../types';
import { formatMoney } from '../lib/format';

interface TotalsProps {
  totals: CartTotals;
}

export const Totals = ({ totals }: TotalsProps) => (
  <dl className="totals">
    <div>
      <dt>Subtotal</dt>
      <dd>{formatMoney(totals.subtotal)}</dd>
    </div>

    {totals.promotionDiscount.amount > 0 && (
      <div className="totals__discount">
        <dt>Promociones</dt>
        <dd>-{formatMoney(totals.promotionDiscount)}</dd>
      </div>
    )}

    {totals.couponDiscount.amount > 0 && (
      <div className="totals__discount">
        <dt>Cupones</dt>
        <dd>-{formatMoney(totals.couponDiscount)}</dd>
      </div>
    )}

    <div>
      <dt>Envío</dt>
      <dd>{totals.freeShipping ? 'Gratis' : formatMoney(totals.shipping)}</dd>
    </div>

    <div>
      <dt>Impuestos</dt>
      <dd>{formatMoney(totals.tax)}</dd>
    </div>

    <div className="totals__total">
      <dt>Total</dt>
      <dd>{formatMoney(totals.total)}</dd>
    </div>

    <p className="totals__hint">
      {totals.unitCount} {totals.unitCount === 1 ? 'artículo' : 'artículos'} ·{' '}
      {totals.distinctItems} {totals.distinctItems === 1 ? 'referencia' : 'referencias'}
    </p>
  </dl>
);

interface CouponBoxProps {
  applied: { code: string; description: string; discountAmount: { amount: number; currency: string } }[];
  onApply: (code: string) => void;
  onRemove: (code: string) => void;
  pending: boolean;
}

export const CouponBox = ({ applied, onApply, onRemove, pending }: CouponBoxProps) => {
  const [code, setCode] = useState('');

  const submit = (event: React.FormEvent): void => {
    event.preventDefault();
    const normalized = code.trim();
    if (!normalized) return;
    onApply(normalized);
    setCode('');
  };

  return (
    <section className="coupons">
      <h4>Cupones</h4>
      <form onSubmit={submit} className="coupons__form">
        <input
          type="text"
          value={code}
          placeholder="BIENVENIDA10"
          onChange={(event) => setCode(event.target.value)}
          disabled={pending}
          aria-label="Código de cupón"
        />
        <button type="submit" disabled={pending || code.trim() === ''}>
          Aplicar
        </button>
      </form>

      {applied.length > 0 && (
        <ul className="coupons__list">
          {applied.map((coupon) => (
            <li key={coupon.code}>
              <span>
                <strong>{coupon.code}</strong> · {coupon.description}
              </span>
              <span className="coupons__amount">
                {coupon.discountAmount.amount > 0
                  ? `-${formatMoney(coupon.discountAmount)}`
                  : 'envío gratis'}
              </span>
              <button type="button" onClick={() => onRemove(coupon.code)} aria-label="Quitar cupón">
                ×
              </button>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
};

import type { CartView } from '../types';
import { formatMoney } from '../lib/format';
import { CouponBox, Totals } from './Totals';

interface CartPanelProps {
  view: CartView | null;
  pending: ReadonlySet<string>;
  onSetQuantity: (productId: string, quantity: number) => void;
  onRemove: (productId: string) => void;
  onClear: () => void;
  onApplyCoupon: (code: string) => void;
  onRemoveCoupon: (code: string) => void;
  onCheckout: () => void;
}

export const CartPanel = ({
  view,
  pending,
  onSetQuantity,
  onRemove,
  onClear,
  onApplyCoupon,
  onRemoveCoupon,
  onCheckout,
}: CartPanelProps) => {
  if (!view) {
    return (
      <aside className="cart cart--empty">
        <h2>Tu carrito</h2>
        <p>Cargando el carrito…</p>
      </aside>
    );
  }

  const { cart, totals } = view;

  return (
    <aside className="cart">
      <header className="cart__header">
        <h2>
          Tu carrito <span className="cart__count">{totals.unitCount}</span>
        </h2>
        {cart.lines.length > 0 && (
          <button type="button" className="link" onClick={onClear}>
            Vaciar
          </button>
        )}
      </header>

      {cart.lines.length === 0 ? (
        <p className="cart__empty-message">
          Todavía no hay productos. Añade alguno desde el catálogo.
        </p>
      ) : (
        <ul className="cart__lines">
          {cart.lines.map((line) => {
            const busy = pending.has(`qty:${line.productId}`);
            return (
              <li key={line.id} className="cart-line">
                <div className="cart-line__info">
                  <strong>{line.name}</strong>
                  <span className="cart-line__sku">{line.sku}</span>
                  <span className="cart-line__price">{formatMoney(line.unitPrice)}</span>
                </div>

                <div className="cart-line__actions">
                  <div className="quantity">
                    <button
                      type="button"
                      onClick={() => onSetQuantity(line.productId, line.quantity - 1)}
                      disabled={busy}
                      aria-label={`Quitar una unidad de ${line.name}`}
                    >
                      −
                    </button>
                    <span aria-live="polite">{line.quantity}</span>
                    <button
                      type="button"
                      onClick={() => onSetQuantity(line.productId, line.quantity + 1)}
                      disabled={busy}
                      aria-label={`Añadir una unidad de ${line.name}`}
                    >
                      +
                    </button>
                  </div>

                  <span className="cart-line__total">{formatMoney(line.lineTotal)}</span>

                  <button
                    type="button"
                    className="link link--danger"
                    onClick={() => onRemove(line.productId)}
                    disabled={pending.has(`rm:${line.productId}`)}
                  >
                    Eliminar
                  </button>
                </div>
              </li>
            );
          })}
        </ul>
      )}

      <CouponBox
        applied={totals.appliedCoupons}
        onApply={onApplyCoupon}
        onRemove={onRemoveCoupon}
        pending={pending.has('apply-coupon')}
      />

      <Totals totals={totals} />

      <button
        type="button"
        className="checkout"
        onClick={onCheckout}
        disabled={cart.lines.length === 0 || pending.has('checkout')}
      >
        {pending.has('checkout') ? 'Procesando…' : 'Finalizar compra'}
      </button>

      <p className="cart__meta">
        Carrito <code>{cart.id.slice(0, 8)}</code> · versión {cart.version}
      </p>
    </aside>
  );
};

import type { Notice } from '../hooks/useCart';

interface NoticeStackProps {
  notices: readonly Notice[];
  onDismiss: (id: number) => void;
}

export const NoticeStack = ({ notices, onDismiss }: NoticeStackProps) => (
  <div className="notices" role="status" aria-live="polite">
    {notices.map((notice) => (
      <div key={notice.id} className={`notice notice--${notice.kind}`}>
        <span>{notice.message}</span>
        <button type="button" onClick={() => onDismiss(notice.id)} aria-label="Cerrar aviso">
          ×
        </button>
      </div>
    ))}
  </div>
);

import { useEffect, useMemo, useState } from 'react';
import { cartApi } from './api/cart-api';
import { CartPanel } from './components/CartPanel';
import { NoticeStack } from './components/NoticeStack';
import { ProductCard } from './components/ProductCard';
import { useCart } from './hooks/useCart';
import type { CatalogProduct } from './types';

const CATEGORIES = ['todo', 'café', 'accesorios', 'chocolate', 'otros'];

export const App = () => {
  const cart = useCart();
  const [products, setProducts] = useState<CatalogProduct[]>([]);
  const [category, setCategory] = useState('todo');
  const [search, setSearch] = useState('');
  const [loadingProducts, setLoadingProducts] = useState(true);
  const [productsError, setProductsError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;

    const load = async (): Promise<void> => {
      setLoadingProducts(true);
      try {
        const result = await cartApi.listProducts({ customerId: cart.customerId });
        if (!cancelled) {
          setProducts(result.products);
          setProductsError(null);
        }
      } catch (caught) {
        if (!cancelled) setProductsError(caught instanceof Error ? caught.message : String(caught));
      } finally {
        if (!cancelled) setLoadingProducts(false);
      }
    };

    void load();
    return () => {
      cancelled = true;
    };
  }, [cart.customerId]);

  const visibleProducts = useMemo(() => {
    const query = search.trim().toLowerCase();
    return products.filter((product) => {
      const matchesCategory = category === 'todo' || product.category === category;
      const matchesSearch =
        query === '' ||
        product.name.toLowerCase().includes(query) ||
        product.sku.toLowerCase().includes(query) ||
        (product.description ?? '').toLowerCase().includes(query);
      return matchesCategory && matchesSearch;
    });
  }, [products, category, search]);

  const quantitiesByProduct = useMemo(() => {
    const map = new Map<string, number>();
    for (const line of cart.view?.cart.lines ?? []) {
      map.set(line.productId, line.quantity);
    }
    return map;
  }, [cart.view]);

  return (
    <div className="layout">
      <header className="topbar">
        <div className="topbar__brand">
          <span className="topbar__logo">☕</span>
          <div>
            <h1>Tienda</h1>
            <p>Carrito de compra escalable · Fastify + Redis + React</p>
          </div>
        </div>

        <label className="topbar__customer">
          Cliente
          <input
            type="text"
            value={cart.customerId}
            onChange={(event) => cart.changeCustomer(event.target.value)}
            aria-label="Identificador de cliente"
          />
        </label>
      </header>

      <NoticeStack notices={cart.notices} onDismiss={cart.dismissNotice} />

      <main className="content">
        <section className="catalog">
          <div className="catalog__toolbar">
            <input
              type="search"
              placeholder="Buscar café, accesorios…"
              value={search}
              onChange={(event) => setSearch(event.target.value)}
              aria-label="Buscar productos"
            />
            <div className="catalog__categories">
              {CATEGORIES.map((item) => (
                <button
                  key={item}
                  type="button"
                  className={category === item ? 'chip chip--active' : 'chip'}
                  onClick={() => setCategory(item)}
                >
                  {item}
                </button>
              ))}
            </div>
          </div>

          {cart.status === 'error' && <p className="error">No se pudo cargar el carrito.</p>}
          {productsError && <p className="error">{productsError}</p>}

          {loadingProducts ? (
            <p className="muted">Cargando el catálogo…</p>
          ) : (
            <div className="catalog__grid">
              {visibleProducts.map((product) => (
                <ProductCard
                  key={product.id}
                  product={product}
                  onAdd={(productId) => void cart.addItem(productId, 1)}
                  pending={cart.pending.has(`add:${product.id}`)}
                  inCart={quantitiesByProduct.get(product.id) ?? 0}
                />
              ))}
            </div>
          )}
        </section>

        <CartPanel
          view={cart.view}
          pending={cart.pending}
          onSetQuantity={(productId, quantity) => void cart.setQuantity(productId, quantity)}
          onRemove={(productId) => void cart.removeItem(productId)}
          onClear={() => void cart.clear()}
          onApplyCoupon={(code) => void cart.applyCoupon(code)}
          onRemoveCoupon={(code) => void cart.removeCoupon(code)}
          onCheckout={() => void cart.checkout()}
        />
      </main>
    </div>
  );
};

import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { App } from './App';
import './styles.css';

const container = document.getElementById('root');
if (!container) throw new Error('The #root element is missing in index.html');

createRoot(container).render(
  <StrictMode>
    <App />
  </StrictMode>,
);

:root {
  --bg: #0f1115;
  --surface: #171a21;
  --surface-2: #1f232c;
  --border: #2a2f3a;
  --text: #eef1f6;
  --muted: #9aa4b2;
  --accent: #f0a35e;
  --accent-strong: #e08a3c;
  --success: #4ade80;
  --warning: #fbbf24;
  --danger: #f87171;
  --radius: 14px;
  color-scheme: dark;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: radial-gradient(circle at 20% -10%, #1d2230 0%, var(--bg) 55%);
  color: var(--text);
  font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  min-height: 100vh;
}

.layout {
  max-width: 1240px;
  margin: 0 auto;
  padding: 24px 20px 64px;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--border);
  margin-bottom: 24px;
}

.topbar__brand {
